import{z as r,x as s,o as t,c as A,q as e,j as n,D as E,d as B,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"回望期权","description":"","frontmatter":{"title":"回望期权","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/lookback-options.md","filePath":"quant/lookback-options.md","lastUpdated":1791063341000}'),_={name:"quant/lookback-options.md"};function p(d,a,m,u,h,T){const o=s("Mermaid");return t(),A("div",null,[a[2]||(a[2]=e('<h1 id="回望期权" tabindex="-1">回望期权 <a class="header-anchor" href="#回望期权" aria-label="Permalink to &quot;回望期权&quot;">​</a></h1><div class="epigraph"><p>浮动回望把执行价换成路径上的极值；固定回望把支付换成极值与固定 K 的差。状态必须包含到目前为止的最大或最小，而不是只盯现价。</p><footer>—— Goldman, Sosin and Gatto, Path Dependent Options: &quot;Buy at the Low, Sell at the High&quot;, Journal of Finance, 1979</footer></div><p><a href="/quant/asian-options">上一课</a>把路径压成平均，凸性被平滑。本课的缺口是另一类统计量：<strong>极值。</strong> 回望看涨「在最低点买」、回望看跌「在最高点卖」，支付依赖 \\(m_T=\\inf_{u\\le T}S_u\\) 或 \\(M_T=\\sup_{u\\le T}S_u\\)。后课数字期权会把支付收成触碰示性；这里先把连续极值在 GBM 下的解析结构写清，并接到离散观察。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>浮动执行价回望看涨支付 \\(S_T-m_T\\)，固定执行价回望看涨支付 \\((M_T-K)^+\\)。两者都不是香草，也不能用亚式的矩匹配糊弄：极值的分布由反射原理与联合密度 \\((S_T,M_T)\\) 决定，尾部比平均厚得多。问题是：连续监控下 Goldman–Sosin–Gatto 与后续 Conze–Viswanathan 给出闭式；交易所与权证几乎都是离散观察（日频或周频），连续公式会高估触达更优极值的概率，从而高估价格。</p><p>第二句话是对冲。回望的 Delta 在现价接近已实现极值时变得尖锐：再创新高，\\(M_t\\) 跟着走，支付的局部行为像持有更多标的。把回望当「杠杆香草」用一个更高的 Vega 去套，会在新高附近把 Gamma 方向做反。</p><p><span class="marginnote">数字实例：一条路径的最低点 \\(m=80\\)、到期价 \\(S_T=100\\)，浮动回望看涨就付 \\(100-80=20\\)；同路径的固定回望（\\(K=90\\)）付 \\(M-90\\)。同一句「买在最低」换算成两个不同的支付函数——先分清你谈的是哪一种。</span></p>',7)),(t(),n(l,null,{default:E(()=>[i(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20Path%5B%22%E5%88%B0%E6%9C%9F%E8%B7%AF%E5%BE%84%3A%20%E7%BB%88%E7%82%B9%20S_T%2C%20%E6%9C%80%E4%BD%8E%20m%2C%20%E6%9C%80%E9%AB%98%20M%22%5D%20--%3E%20F%5B%22%E6%B5%AE%E5%8A%A8%E7%9C%8B%E6%B6%A8%3A%20%E6%94%AF%E4%BB%98%20S_T%20%E2%88%92%20m%22%5D%0A%20%20Path%20--%3E%20G%5B%22%E5%9B%BA%E5%AE%9A%E7%9C%8B%E6%B6%A8%3A%20%E6%94%AF%E4%BB%98%20(M%20%E2%88%92%20K)%2B%22%5D%0A%20%20F%20--%3E%20STATE%5B%22%E7%8A%B6%E6%80%81%3A%20(S_t%2C%20%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%9E%81%E5%80%BC)%22%5D%0A%20%20G%20--%3E%20STATE%0A%20%20NEAR%5B%22%E7%8E%B0%E4%BB%B7%E6%8E%A5%E8%BF%91%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%9E%81%E5%80%BC%22%5D%20--%3E%20FREEZE%5B%22S%20%3C%20M%3A%20%E6%9E%81%E5%80%BC%E5%86%BB%E7%BB%93%2C%20%E5%83%8F%E6%89%A7%E8%A1%8C%E4%BB%B7%E9%92%89%E4%BD%8F%E7%9A%84%E6%9C%9F%E6%9D%83%22%5D%0A%20%20NEAR%20--%3E%20MOVE%5B%22S%20%3D%20M%3A%20%E5%86%8D%E5%88%9B%E6%96%B0%E9%AB%98%E5%88%99%E6%9E%81%E5%80%BC%E5%90%8C%E6%AD%A5%E4%B8%8A%E7%A7%BB%22%5D%0A%20%20FREEZE%20--%3E%20DELTA%5B%22Delta%2FGamma%20%E7%BB%93%E6%9E%84%E5%BC%82%E4%BA%8E%E9%A6%99%E8%8D%89%22%5D%0A%20%20MOVE%20--%3E%20DELTA%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h3 id="已实现极值是吸收壁上的状态" tabindex="-1">已实现极值是吸收壁上的状态 <a class="header-anchor" href="#已实现极值是吸收壁上的状态" aria-label="Permalink to &quot;已实现极值是吸收壁上的状态&quot;">​</a></h3><p>记 \\(M_t=\\sup_{u\\le t}S_u\\)。若 \\(S_t\\lt M_t\\)，短期内 \\(M\\) 冻结，合约像执行价钉在 \\(M_t\\) 的期权；若 \\(S_t=M_t\\)，下一步向上，\\(M\\) 与 \\(S\\) 一起动，有效 Gamma 与普通期权不同。这与亚式的 \\((S,A)\\) 类似——都是二维状态——但极值是非可微的运行最大值，PDE 的边界条件写在 \\(S=M\\) 上，不是写在平均的积分核上。</p><p><span class="marginnote">回望不是障碍。障碍在触碰时改变合约身份（敲入/敲出）；回望在触碰时更新执行价或支付基准，合约继续活着。解析技巧都用反射，经济含义不要混。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>连续 GBM、连续监控：用 \\((S_t,M_t)\\) 的联合分布写出欧式回望价格，参数仍是 \\(r,q,\\sigma,T\\)。离散监控：没有简单闭式，用带运行最大的树、或对离散采样的路径做 <a href="/quant/mc-pricing">蒙特卡洛</a>；连续性修正的精神与 Broadie–Glasserman–Kou 类似，但系数不是障碍那一个 \\(\\beta\\)，不要直接挪用 <a href="/quant/barrier-monitoring">障碍监控频率</a> 的 \\(H&#39;\\)。</p><p><span class="marginnote">离散监控翻译成大白话：合约只「每天收盘看一眼」最高最低价，而不是每微秒盯盘。看得越勤，越容易抓到更极端的值，期权越贵；日频观察天然抓不到盘中极端，所以拿连续公式去定日频合约，会系统性偏贵。</span></p><p>浮动与固定通过恒等式联系（在无股息等简化下），实现时仍应按条款分别测。美式回望更常见于权证，提前行权破坏欧式闭式，应走树或回归。不要用 <a href="/quant/bsm">BSM</a> 的 \\(N(d_1)\\) 去冒充回望 Delta。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>布朗运动的运行最大与终点的联合律来自反射：碰到高位再回到 \\(S_T\\) 的路径，与从未碰到的路径，测度可以配对。这给出 \\(M_T\\) 的边际，从而给出固定回望的价格。浮动回望则是 \\(S_T\\) 与 \\(m_T\\) 的差，复制直觉是「一直有权在历史最低买」——代价是全程持有更大的凸性。波动上升同时抬高极值分布与终点分散，Vega 通常大于同类香草；这不是「回望=更高 vol 的香草」，因为偏斜与离散观察会把这层优势削掉。</p>',9)),(t(),n(l,null,{default:E(()=>[i(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E8%B7%AF%E5%BE%84%20S%22%5D%20--%3E%20M%5B%22%E8%BF%90%E8%A1%8C%E6%9C%80%E5%A4%A7%E6%88%96%E6%9C%80%E5%B0%8F%22%5D%0A%20%20M%20--%3E%20Fix%5B%22%E5%9B%BA%E5%AE%9A%E5%9B%9E%E6%9C%9B%20%E6%9E%81%E5%80%BC%E5%AF%B9%20K%22%5D%0A%20%20M%20--%3E%20Flt%5B%22%E6%B5%AE%E5%8A%A8%E5%9B%9E%E6%9C%9B%20%E7%BB%88%E7%82%B9%E5%AF%B9%E6%9E%81%E5%80%BC%22%5D%0A%20%20Fix%20--%3E%20St%5B%22%E7%8A%B6%E6%80%81%20S%20%E4%B8%8E%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%9E%81%E5%80%BC%22%5D%0A%20%20Flt%20--%3E%20St%0A%20%20St%20--%3E%20Disc%5B%22%E7%A6%BB%E6%95%A3%E8%A7%82%E5%AF%9F%E5%88%99%E8%BF%9E%E7%BB%AD%E5%85%AC%E5%BC%8F%E9%AB%98%E4%BC%B0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>连续监控闭式对权证日频观察往往偏贵，卖方若按连续报价会被离散现实少付。有股息、离散分红、涨跌停，反射原理不再干净。局部波动与随机波动下极值分布对微笑敏感：回望吃的是路径上的偏斜，不是 ATM。商品与外汇的回望还要定义用即期还是期货、用日内高还是结算价。</p><p>本课不把回望写成交易「买低卖高」的保证。支付是期权，权利金已经把极值的风险中性期望收进去；历史「曾经摸到过」不能当未来极值的估计。</p><p><span class="marginnote">常见误区：以为「回望 = 一定能买在最低、卖在最高」。极值是事后才知道的统计量；买方在期初就付了权利金，期望上恰好为这份「事后最优」的凸性付足了钱。它不是免费午餐，而是把路径极值风险定价后的产物。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回望的状态是现价加已实现极值；浮动钉执行价，固定钉支付。</li><li>连续 GBM 有反射闭式；离散观察必须另做，不能抄障碍平移系数。</li><li>新高/新低附近希腊值结构与香草不同，不能用更高 Vega 的香草代替。</li><li>出处：Goldman, Sosin and Gatto, <em>Journal of Finance</em>, 1979；Conze and Viswanathan, <em>Journal of Finance</em>, 1991。</li></ul>',6))])}const C=r(_,[["render",p]]);export{c as __pageData,C as default};
